// Generates the platform files from tokens.json (#141): `pnpm tokens`.
// `--check` only compares and fails when a generated file is outdated (CI,
// test/tokens.test.ts). No dependency besides Prettier from the repo root,
// which formats the CSS and TypeScript output like every other file.
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, relative, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import * as prettier from 'prettier'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../../..')
const tokens = JSON.parse(readFileSync(resolve(root, 'packages/design-tokens/tokens.json'), 'utf8'))
const HEADER = 'Generated by packages/design-tokens from tokens.json (pnpm tokens). Do not edit.'
const REM_PX = 16

const remToPx = (value) => {
  const match = /^(\d+(?:\.\d+)?)(rem|px)$/.exec(value)
  if (!match) throw new Error(`unsupported size ${value}`)
  return match[2] === 'rem' ? Number(match[1]) * REM_PX : Number(match[1])
}
const camel = (name) => name.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase())
const pascal = (name) => camel(name).replace(/^./, (c) => c.toUpperCase())
const kotlinNumber = (n) => (Number.isInteger(n) ? String(n) : String(Number(n.toFixed(2))))
const kotlinColor = (hex) => `Color(0xFF${hex.slice(1).toUpperCase()})`

function css() {
  const theme = (name, mode, flags) => [
    `@plugin 'daisyui/theme' {`,
    `  name: '${name}';`,
    ...flags.map((flag) => `  ${flag}: true;`),
    `  color-scheme: ${mode};`,
    ...Object.entries(tokens.colors[mode]).map(([key, value]) => `  --color-${key}: ${value};`),
    ...Object.entries(tokens.shape).map(([key, value]) => `  --${key}: ${value};`),
    `  --depth: 0;`,
    `  --noise: 0;`,
    `}`,
  ]
  const density = (mode) => [
    `  --fma-row-py: ${tokens.density[mode]['row-py']};`,
    `  --fma-row-px: ${tokens.density[mode]['row-px']};`,
    `  --fma-folder-py: ${tokens.density[mode]['folder-py']};`,
    `  --fma-snippet-display: ${tokens.density[mode].snippet ? 'block' : 'none'};`,
  ]
  return [
    `/* ${HEADER} */`,
    '',
    ...theme('fma-light', 'light', ['default']),
    '',
    ...theme('fma-dark', 'dark', ['prefersdark']),
    '',
    '/* Spacing and type scale (#112), density "normal". */',
    ':root {',
    ...Object.entries(tokens.sizes).map(([key, value]) => `  --fma-${key}: ${value};`),
    ...density('normal'),
    '}',
    '',
    '/* Density "kompakt" (#112): more messages on screen, no preview line. */',
    ":root[data-density='compact'] {",
    ...density('compact'),
    '}',
    '',
  ].join('\n')
}

function typescript() {
  const palette = (mode) =>
    Object.entries(tokens.colors[mode]).map(([key, value]) => `    '${key}': '${value}',`)
  return [
    `// ${HEADER}`,
    '',
    '/** Built-in palettes of the app (daisyUI theme colors), light and dark. */',
    'export const BUILTIN_THEME_COLORS = {',
    '  light: {',
    ...palette('light'),
    '  },',
    '  dark: {',
    ...palette('dark'),
    '  },',
    '} as const',
    '',
    '/** Background colors of the account icons; white text on each is AA. */',
    'export const ACCOUNT_COLORS = [',
    ...tokens.accountColors.map((c) => `  '${c.value}', // ${c.name}`),
    '] as const',
    '',
  ].join('\n')
}

function php() {
  const palette = (mode) =>
    Object.entries(tokens.colors[mode]).map(([key, value]) => `            '${key}' => '${value}',`)
  return [
    '<?php',
    '',
    'declare(strict_types=1);',
    '',
    'namespace Fma\\Themes;',
    '',
    `/** ${HEADER} */`,
    'final class DesignTokens',
    '{',
    '    /** Built-in palettes of the app (daisyUI theme colors), light and dark. */',
    '    public const COLORS = [',
    "        'light' => [",
    ...palette('light'),
    '        ],',
    "        'dark' => [",
    ...palette('dark'),
    '        ],',
    '    ];',
    '}',
    '',
  ].join('\n')
}

function kotlin() {
  const colors = (mode) =>
    Object.entries(tokens.colors[mode]).map(
      ([key, value]) => `        val ${camel(key)} = ${kotlinColor(value)}`,
    )
  const scheme = (mode, fn) => {
    const c = `FmaColors.${pascal(mode)}`
    return [
      `val Fma${pascal(mode)}ColorScheme = ${fn}(`,
      `    primary = ${c}.primary,`,
      `    onPrimary = ${c}.primaryContent,`,
      `    secondary = ${c}.secondary,`,
      `    onSecondary = ${c}.secondaryContent,`,
      `    tertiary = ${c}.accent,`,
      `    onTertiary = ${c}.accentContent,`,
      `    background = ${c}.base100,`,
      `    onBackground = ${c}.baseContent,`,
      `    surface = ${c}.base100,`,
      `    onSurface = ${c}.baseContent,`,
      `    surfaceVariant = ${c}.base200,`,
      `    onSurfaceVariant = ${c}.baseContent,`,
      `    outline = ${c}.base300,`,
      `    error = ${c}.error,`,
      `    onError = ${c}.errorContent,`,
      ')',
    ]
  }
  const size = ([key, value]) => {
    const unit = key.startsWith('text-') ? 'sp' : 'dp'
    return `    val ${camel(key)} = ${kotlinNumber(remToPx(value))}.${unit}`
  }
  const density = (mode) => {
    const d = tokens.density[mode]
    return `    val ${pascal(mode)} = FmaDensity(rowPaddingVertical = ${kotlinNumber(remToPx(d['row-py']))}.dp, rowPaddingHorizontal = ${kotlinNumber(remToPx(d['row-px']))}.dp, folderPaddingVertical = ${kotlinNumber(remToPx(d['folder-py']))}.dp, showSnippet = ${d.snippet})`
  }
  return [
    `// ${HEADER}`,
    '// Compose Multiplatform theme for apps/mobile (ADR-0015); 1rem = 16dp/sp.',
    'package fma.design',
    '',
    'import androidx.compose.material3.darkColorScheme',
    'import androidx.compose.material3.lightColorScheme',
    'import androidx.compose.ui.graphics.Color',
    'import androidx.compose.ui.unit.Dp',
    'import androidx.compose.ui.unit.dp',
    'import androidx.compose.ui.unit.sp',
    '',
    '/** daisyUI theme colors of the web app, by name. */',
    'object FmaColors {',
    '    object Light {',
    ...colors('light'),
    '    }',
    '',
    '    object Dark {',
    ...colors('dark'),
    '    }',
    '}',
    '',
    ...scheme('light', 'lightColorScheme'),
    '',
    ...scheme('dark', 'darkColorScheme'),
    '',
    '/** Spacing, radii and type scale. */',
    'object FmaSizes {',
    ...Object.entries(tokens.shape)
      .filter(([key]) => key.startsWith('radius-'))
      .map(([key, value]) => size([`shape-${key}`, value])),
    ...Object.entries(tokens.sizes).map(size),
    '}',
    '',
    'data class FmaDensity(val rowPaddingVertical: Dp, val rowPaddingHorizontal: Dp, val folderPaddingVertical: Dp, val showSnippet: Boolean) {',
    '    companion object {',
    ...['normal', 'compact'].map((mode) => '    ' + density(mode)),
    '    }',
    '}',
    '',
    '/** Background colors of the account icons (white initials are AA on each). */',
    'val FmaAccountColors = listOf(',
    ...tokens.accountColors.map((c) => `    ${kotlinColor(c.value)}, // ${c.name}`),
    ')',
    '',
    `/** Icons of the ${tokens.icons.set} set the app uses (same names as on the web). */`,
    'val FmaIconNames = listOf(',
    ...tokens.icons.names.map((name) => `    "${name}",`),
    ')',
    '',
  ].join('\n')
}

async function formatted(file, source) {
  if (!/\.(css|ts)$/.test(file)) return source
  const options = (await prettier.resolveConfig(file)) ?? {}
  return prettier.format(source, { ...options, filepath: file })
}

const outputs = {
  'apps/web/app/assets/css/tokens.css': css(),
  'packages/shared/src/design-tokens.ts': typescript(),
  'apps/server-php/src/Themes/DesignTokens.php': php(),
  'packages/design-tokens/generated/FmaTokens.kt': kotlin(),
}

const check = process.argv.includes('--check')
const outdated = []
for (const [path, source] of Object.entries(outputs)) {
  const file = resolve(root, path)
  const content = await formatted(file, source)
  let current = null
  try {
    current = readFileSync(file, 'utf8')
  } catch {
    // missing: written below, or outdated in --check
  }
  if (current === content) continue
  if (check) outdated.push(relative(root, file))
  else writeFileSync(file, content)
}
if (outdated.length > 0) {
  process.stderr.write(`outdated, run pnpm tokens: ${outdated.join(', ')}\n`)
  process.exit(1)
}
